 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Horizontal bars are the dense rows; the last such row is the base of
    # the downward vertical rays.
    bars = [r for r, row in enumerate(g) if sum(v != 0 for v in row) >= 4]
    if not bars:
        return g
    last = max(bars)
    rays = [c for c in range(w) if any(g[r][c] != 0 for r in range(last + 1, h))]

    # Close single-cell breaks in horizontal bars at ray columns.
    for r in bars:
        for c in rays:
            if g[r][c] == 0 and 0 < c < w - 1 and g[r][c-1] != 0 and g[r][c-1] == g[r][c+1]:
                g[r][c] = g[r][c-1]

    # Extend each ray upward, with each horizontal band's color determined
    # by the nearest bar below it that crosses the ray's column.
    for c in rays:
        start = min(r for r in range(last + 1, h) if g[r][c] != 0)
        for y in range(start):
            candidates = [r for r in bars if r >= y and g[r][c] != 0]
            if candidates:
                r = min(candidates)
                g[y][c] = g[r][c]
    return g
